import type { VisionHand } from '../../src/vision-types.js';

export function createHand(gesture = 'None', gestureScore = 0.95): VisionHand {
  const landmarks = Array.from({ length: 21 }, (_, index) => ({ x: 0.3 + index * 0.004, y: 0.5, z: 0 }));
  landmarks[0] = { x: 0.35, y: 0.7, z: 0 };
  landmarks[4] = { x: 0.18, y: 0.52, z: 0 };
  landmarks[5] = { x: 0.29, y: 0.5, z: 0 };
  landmarks[6] = { x: 0.29, y: 0.4, z: 0 };
  landmarks[7] = { x: 0.29, y: 0.3, z: 0 };
  landmarks[8] = { x: 0.29, y: 0.2, z: 0 };
  landmarks[17] = { x: 0.41, y: 0.5, z: 0 };
  return { handedness: 'Left', score: 0.99, gesture, gestureScore, landmarks };
}

export function createHeartHands(): VisionHand[] {
  const coordinates = [
    [0.245, 0.65], [0.28, 0.56], [0.37, 0.53], [0.44, 0.49], [0.498, 0.45],
    [0.34, 0.50], [0.40, 0.28], [0.465, 0.265], [0.498, 0.31],
    [0.31, 0.53], [0.37, 0.40], [0.44, 0.33], [0.49, 0.31],
    [0.29, 0.57], [0.34, 0.42], [0.40, 0.35], [0.46, 0.30],
    [0.27, 0.60], [0.31, 0.45], [0.36, 0.36], [0.41, 0.30],
  ];
  const left = createHand();
  left.landmarks = coordinates.map(([x, y]) => ({ x, y, z: 0 }));
  const right = createHand();
  right.handedness = 'Right';
  right.landmarks = left.landmarks.map(({ x, y, z }) => ({ x: 1 - x, y, z }));
  return [left, right];
}

